public class LootTableManager {
	private final Map<ResourceLocation, LootPool> pools;
	private final Map<ResourceLocation, LootFunction> functions;
	private final Map<ResourceLocation, LootCondition> conditions;

	public LootTableManager() {
		this.pools = new HashMap<>();
		this.functions = new HashMap<>();
		this.conditions = new HashMap<>();
	}

	public void add(ResourceLocation id, LootPool pool) {
		pools.put(id, pool);
	}

	public void modify(ResourceLocation id, Consumer<LootPool.Builder> modifier) {
		var existing = pools.get(id);
		if (existing != null) {
			var builder = existing.asPool().builder();
			modifier.accept(builder);
			pools.put(id, builder.build());
		}
	}

	public void remove(ResourceLocation id) {
		pools.remove(id);
	}

	public LootPool getLootTable(ResourceLocation id) {
		return pools.get(id);
	}
}
